import{_ as t}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as a}from"./chunks/M-S-Search.C3B92iCp.js";import{_ as i}from"./chunks/CrystalBall.BdqnOTQQ.js";import{_ as s,o as r,c as o,a3 as n}from"./chunks/framework.g9mfNVRQ.js";const _=JSON.parse('{"title":"Paramètres","description":"","frontmatter":{"source_hash":"4f30078921","source_commit":"7a18e7c","i18n_outdated":true},"headers":[],"relativePath":"fr/use/settings.md","filePath":"fr/use/settings.md"}'),p={name:"fr/use/settings.md"};function d(l,e,c,u,m,h){return r(),o("div",null,[...e[0]||(e[0]=[n('<div class="admonition xdrip"><p class="admonition-title"><img src="'+t+'" style="zoom:75%;"></p><p> Paramètres</p></div><p>xDrip comporte de nombreux paramètres : si vous ne trouvez pas ce que vous cherchez, utilisez la loupe de recherche en haut à droite et saisissez le mot-clé recherché.</p><img src="'+a+'" style="zoom:75%;"><br><h3 id="glucose-units" tabindex="-1">Unité de glycémie <a class="header-anchor" href="#glucose-units" aria-label="Permalink to &quot;Unité de glycémie {#glucose-units}&quot;">​</a></h3><div class="admonition xdrip"><p class="admonition-title">Unité de glycémie</p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_ruler_grey600_48dp.png" style="width:5%;"> Unités mmol/l ou mg/dl, Haute, Basse</p></div><p>Dans ce menu, vous pouvez choisir les unités utilisées par xDrip (mg/dl ou mmol/l) et définir les cibles haute et basse.</p><div class="admonition xdripitem"><p class="admonition-title">Unité de glycémie</p><p> mg/dl ou mmol/l</p></div><p>Ces deux cibles déterminent quand les points de glycémie du graphique changent de couleur au-dessus ou en dessous de la cible.</p><div class="admonition xdripitem"><p class="admonition-title">Valeur Haute</p><p> 170</p></div><div class="admonition xdripitem"><p class="admonition-title">Valeur Basse</p><p> 70</p></div><h3 id="alarms-and-alerts" tabindex="-1"><a href="./alarms.html">Alarmes et alertes</a> <a class="header-anchor" href="#alarms-and-alerts" aria-label="Permalink to &quot;[Alarmes et alertes](./alarms) {#alarms-and-alerts}&quot;">​</a></h3><div class="admonition xdrip"><p class="admonition-title">Alarmes et alertes</p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_add_alert_grey600_48dp.png" style="width:5%;"> Glycémie, calibration et autres alertes</p></div><h3 id="hardware-data-source" tabindex="-1"><a href="./../install/datasource.html">Source de données matérielle</a> <a class="header-anchor" href="#hardware-data-source" aria-label="Permalink to &quot;[Source de données matérielle](../install/datasource) {#hardware-data-source}&quot;">​</a></h3><p>Ces paramètres dépendent de la source de données sélectionnée.</p><div class="admonition xdrip"><p class="admonition-title">Source de données matérielle</p></div><h3 id="nfc-scan-features" tabindex="-1"><a href="./NFC.html">Fonctionnalités de scan NFC</a> <a class="header-anchor" href="#nfc-scan-features" aria-label="Permalink to &quot;[Fonctionnalités de scan NFC](./NFC) {#nfc-scan-features}&quot;">​</a></h3><p>Ce menu n&#39;est visible que si vous choisissez une source de données Libre Bluetooth dans Source de données matérielle. Si vous devez y accéder pour modifier les paramètres de lissage des capteurs Libre, changez temporairement de source de données.</p><div class="admonition xdrip"><p class="admonition-title">Fonctionnalités de scan NFC</p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_nfc_grey600_48dp.png" style="width:5%;"> Options pour scanner les capteurs basés sur NFC avec le combiné du téléphone</p></div><h3 id="auto-configure" tabindex="-1"><a href="./copysettings.html#auto-configure">Configuration automatique</a> <a class="header-anchor" href="#auto-configure" aria-label="Permalink to &quot;[Configuration automatique](./copysettings#auto-configure) {#auto-configure}&quot;">​</a></h3><p>Configuration automatique vous aide à copier les paramètres entre deux applications xDrip installées sur des téléphones différents. Cette fonction et <a href="./copysettings.html#show-settings-qr-code">Affichage QR codes</a> se trouvent toutes deux dans l&#39;écran &quot;Copie de paramètres&quot;.</p><div class="admonition xdrip"><p class="admonition-title">Configuration automatique</p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_qrscan.png" style="width:5%;"> Configuration automatique en utilisant un code-barres.</p></div><h3 id="cloud-upload" tabindex="-1"><a href="./cloud.html">Chargement vers Cloud</a> <a class="header-anchor" href="#cloud-upload" aria-label="Permalink to &quot;[Chargement vers Cloud](./cloud) {#cloud-upload}&quot;">​</a></h3><p>Chargement vers Cloud permet de configurer diverses fonctions de partage et d&#39;envoi de données.</p><div class="admonition xdrip"><p class="admonition-title">Chargement vers Cloud</p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_cloud_upload_grey600_48dp.png" style="width:5%;"> Options pour le chargement vers Nightscout, MongoDB ou Dexcom Share</p></div><h3 id="glucose-meters" tabindex="-1"><a href="./glucometer.html">Lecteurs de Glycémie</a> <a class="header-anchor" href="#glucose-meters" aria-label="Permalink to &quot;[Lecteurs de Glycémie](./glucometer) {#glucose-meters}&quot;">​</a></h3><p>Vous pouvez connecter des lecteurs de glycémie compatibles à xDrip.</p><div class="admonition xdrip"><p class="admonition-title">Lecteurs de Glycémie</p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_touch_app_grey600_48dp.png" style="width:5%;"> Options pour les lecteurs de glycémie sans fil</p></div><h3 id="smart-watch-features" tabindex="-1"><a href="./../smartwatch/smartwatch.html">Options montre intelligente</a> <a class="header-anchor" href="#smart-watch-features" aria-label="Permalink to &quot;[Options montre intelligente](../smartwatch/smartwatch) {#smart-watch-features}&quot;">​</a></h3><p>Diverses montres connectées peuvent recevoir et afficher les données de xDrip ; certaines peuvent même servir de collecteur autonome.</p><div class="admonition xdrip"><p class="admonition-title">Options montre intelligente</p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_watch_grey600_48dp.png" style="width:5%;"> Options pour différentes montres</p></div><h3 id="speak-readings" tabindex="-1"><a href="./speak.html">Prononcer les valeurs</a> <a class="header-anchor" href="#speak-readings" aria-label="Permalink to &quot;[Prononcer les valeurs](./speak) {#speak-readings}&quot;">​</a></h3><p>xDrip peut utiliser le téléphone pour annoncer à voix haute les valeurs et les alertes.</p><div class="admonition xdrip"><p class="admonition-title">Prononcer les valeurs</p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_speak_reading_grey600_48dp.png" style="width:5%;"> Si le téléphone a des capacités text-to-speech, il prononcera chaque nouvelle lecture.</p></div><h3 id="inter-app-settings" tabindex="-1"><a href="./interapp.html">Paramètres inter applications</a> <a class="header-anchor" href="#inter-app-settings" aria-label="Permalink to &quot;[Paramètres inter applications](./interapp) {#inter-app-settings}&quot;">​</a></h3><p>xDrip peut recevoir des données d&#39;autres applications ou leur en envoyer, et servir de serveur web local.</p><div class="admonition xdrip"><p class="admonition-title">Paramètres inter applications</p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_open_in_app_grey600_48dp.png" style="width:5%;"> Pour interagir avec d’autres applications compatibles</p></div><h3 id="less-common-settings" tabindex="-1"><a href="./lesscommon.html">Paramètres moins courants</a> <a class="header-anchor" href="#less-common-settings" aria-label="Permalink to &quot;[Paramètres moins courants](./lesscommon) {#less-common-settings}&quot;">​</a></h3><p>D&#39;autres paramètres sont disponibles dans ce menu.</p><div class="admonition xdrip"><p class="admonition-title">Paramètres moins courants</p><p> Debug et autres options</p></div><h3 id="display" tabindex="-1"><a href="./display.html">xDrip+ Affichage</a> <a class="header-anchor" href="#display" aria-label="Permalink to &quot;[xDrip+ Affichage](./display) {#display}&quot;">​</a></h3><div class="admonition xdrip"><p class="admonition-title">xDrip+ Affichage</p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_chart_areaspline_grey600_48dp.png" style="width:5%;"> Afficher les personnalisations</p></div><h3 id="predictive-simulations" tabindex="-1"><a href="./predictions.html">xDrip+ Simulations prédictives</a> <a class="header-anchor" href="#predictive-simulations" aria-label="Permalink to &quot;[xDrip+ Simulations prédictives](./predictions) {#predictive-simulations}&quot;">​</a></h3><div class="admonition xdrip"><p class="admonition-title">xDrip+ Simulations prédictives</p><p> <img src="'+i+'" style="width:5%;"> Insuline, ratios de glycémie, etc par modèles</p></div><h3 id="xdrip-sync" tabindex="-1"><a href="./sync.html">xDrip+ Synchronisation</a> <a class="header-anchor" href="#xdrip-sync" aria-label="Permalink to &quot;[xDrip+ Synchronisation](./sync) {#xdrip-sync}&quot;">​</a></h3><div class="admonition xdrip"><p class="admonition-title">xDrip+ Synchronisation</p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_google_circles_communities_grey600_48dp.png" style="width:5%;"> Paramètres pour la sync entre appareils</p></div><h3 id="motion-tracking" tabindex="-1"><a href="./motion.html">xDrip+ Détection de Mouvement</a> <a class="header-anchor" href="#motion-tracking" aria-label="Permalink to &quot;[xDrip+ Détection de Mouvement](./motion) {#motion-tracking}&quot;">​</a></h3><div class="admonition xdrip"><p class="admonition-title">xDrip+ Détection de Mouvement</p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_car_connected_grey600_48dp.png" style="width:5%;"> Détection de mouvement et mode véhicule</p></div><h3 id="update-settings" tabindex="-1"><a href="./update.html">xDrip+ Mises à jour</a> <a class="header-anchor" href="#update-settings" aria-label="Permalink to &quot;[xDrip+ Mises à jour](./update) {#update-settings}&quot;">​</a></h3><div class="admonition xdrip"><p class="admonition-title">xDrip+ Mises à jour</p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_briefcase_download_grey600_48dp.png" style="width:5%;"> Mises à jour automatiques, rapports d&#39;incidents et réactions au développeur</p></div><h3 id="show-settings-qr-code" tabindex="-1"><a href="./copysettings.html#show-settings-qr-code">Affichage QR codes</a> <a class="header-anchor" href="#show-settings-qr-code" aria-label="Permalink to &quot;[Affichage QR codes](./copysettings#show-settings-qr-code) {#show-settings-qr-code}&quot;">​</a></h3><p>Cette fonction sert à transférer les paramètres entre téléphones.</p><div class="admonition xdrip"><p class="admonition-title">Affichage QR codes</p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_qrcode_grey600_48dp.png" style="width:5%;"></p></div><h3 id="load-save-settings" tabindex="-1"><a href="./loadsavesettings.html">Charger / Enregistrer les paramètres</a> <a class="header-anchor" href="#load-save-settings" aria-label="Permalink to &quot;[Charger / Enregistrer les paramètres](./loadsavesettings) {#load-save-settings}&quot;">​</a></h3><p>Vous pouvez sauvegarder et restaurer vos paramètres xDrip.</p><div class="admonition xdrip"><p class="admonition-title">Charger / Enregistrer les paramètres</p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_content_save_grey600_48dp.png" style="width:5%;"></p></div><h3 id="insulin-pens" tabindex="-1"><a href="./pens.html">Stylos à Insuline</a> <a class="header-anchor" href="#insulin-pens" aria-label="Permalink to &quot;[Stylos à Insuline](./pens) {#insulin-pens}&quot;">​</a></h3><p>Certains stylos à insuline peuvent être utilisés avec xDrip.</p><div class="admonition xdrip"><p class="admonition-title">Stylos à Insuline</p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_mode_edit_grey_600_48dp.png" style="width:5%;"></p></div><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Dernière modification le 23/11/2026</em></a></p>',61)])])}const b=s(p,[["render",d]]);export{_ as __pageData,b as default};
